/**
 * Language Starter - app logic.
 *
 * Depends on (loaded before, all with `defer`):
 *   window.LS_I18N    - js/i18n.js
 *   window.LSStorage  - js/storage.js
 *   window.LSVoice    - js/voice.js
 *   window.qrcode     - js/vendor/qrcode.min.js (MIT, Kazuhiko Arase)
 *
 * Data comes from data/phrases.json (the only file to edit). When the page
 * is opened from disk (file://) browsers refuse fetch(), so the app loads
 * data/phrases.js instead: the same data, generated by tools/build.mjs.
 *
 * URL parameters: ?from=de&to=ka&ui=de keeps the language pair, so a group
 * leader can send a direct link. ?review=fi shows a plain table for native
 * speakers who check a language (no app, nothing stored or sent).
 */
(function () {
  'use strict';

  var I18N = window.LS_I18N;
  var store = window.LSStorage;
  var voice = window.LSVoice;

  var DATA_URL = 'data/phrases.json';
  var DATA_FALLBACK_URL = 'data/phrases.js';
  var PAGE_URL = 'https://mrlololi.com/Webprojekte/language-starter/';
  var MAIL = 'hello@mrlololi.com';
  var OPTION_COUNT = 4;
  var NEXT_GUARD_MS = 300;
  var GAP = '…';

  /* ------------------------------------------------------------------ */
  /* State                                                               */
  /* ------------------------------------------------------------------ */

  var state = {
    ui: 'en',
    from: '',
    to: '',
    data: null,
    codes: [],                // language codes in data order
    byLang: {},               // lang -> { id -> entry }
    order: [],                // phrase ids in order (n)
    groupOf: {},              // id -> group id
    checkedLang: {},          // lang -> all entries checked
    group: 'intro',           // phrase cards: active topic
    quiz: { group: 'all', dir: 'learn' },
    progress: null,
    round: null,
    lastResult: null,
    options: [],
    answeredAt: 0,
    resetArmed: false,
    screen: 'start'
  };

  function $(id) { return document.getElementById(id); }

  var el = {
    langButtons: $('lang-buttons'),
    status: $('status'),
    fromSelect: $('from-select'),
    toSelect: $('to-select'),
    swapBtn: $('swap-btn'),
    copyBtn: $('copy-btn'),
    copyMsg: $('copy-msg'),
    pickWrap: $('pick-wrap'),
    pickGrid: $('pick-grid'),
    pair: $('pair'),
    draft: $('draft'),
    draftText: $('draft-text'),
    groupChips: $('group-chips'),
    cards: $('cards'),
    storageNotice: $('storage-notice'),
    screens: { start: $('screen-start'), question: $('screen-question'), result: $('screen-result') },
    startForm: $('start-form'),
    startTitle: $('start-title'),
    quizGroups: $('quiz-groups'),
    dirLearn: $('dir-learn-label'),
    dirSay: $('dir-say-label'),
    resumeBtn: $('resume-btn'),
    statKnown: $('stat-known'),
    statBest: $('stat-best'),
    statRounds: $('stat-rounds'),
    resetBtn: $('reset-btn'),
    resetMsg: $('reset-msg'),
    counter: $('q-counter'),
    progressBar: $('q-progress'),
    scoreOk: $('score-ok'),
    scoreBad: $('score-bad'),
    promptLabel: $('q-label'),
    word: $('q-word'),
    translit: $('q-translit'),
    options: $('q-options'),
    feedback: $('q-feedback'),
    nextBtn: $('next-btn'),
    kbdHint: $('kbd-hint'),
    quitBtn: $('quit-btn'),
    resultTitle: $('result-title'),
    ringValue: $('result-ring-value'),
    percentShort: $('r-percent-short'),
    rCorrect: $('r-correct'),
    rTotal: $('r-total'),
    rPercent: $('r-percent'),
    rMessage: $('r-message'),
    rWrongWrap: $('r-wrong-wrap'),
    rWrong: $('r-wrong'),
    retryBtn: $('retry-btn'),
    againBtn: $('again-btn'),
    settingsBtn: $('settings-btn'),
    sheet: $('sheet'),
    printBtn: $('print-btn'),
    thanks: $('thanks'),
    thanksList: $('thanks-list'),
    review: $('review')
  };

  /* ------------------------------------------------------------------ */
  /* i18n                                                                */
  /* ------------------------------------------------------------------ */

  function uiReady(code) {
    return Boolean(I18N[code]) && Object.keys(I18N[code]).length > 0;
  }

  function uiInfo(code) {
    return I18N.languages.filter(function (l) { return l.code === code; })[0] || I18N.languages[1];
  }

  function raw(key) {
    var dict = I18N[state.ui] || {};
    if (Object.prototype.hasOwnProperty.call(dict, key)) return dict[key];
    if (Object.prototype.hasOwnProperty.call(I18N.common, key)) return I18N.common[key];
    var fallback = I18N[I18N.defaultLang] || {};
    return Object.prototype.hasOwnProperty.call(fallback, key) ? fallback[key] : key;
  }

  function t(key, vars) {
    var value = raw(key);
    vars = vars || {};
    if (value && typeof value === 'object' && !Array.isArray(value)) {
      var category = 'other';
      try {
        category = new Intl.PluralRules(uiInfo(state.ui).locale).select(Number(vars.n));
      } catch (error) { /* old browser */ }
      value = value[category] || value.other;
    }
    return String(value).replace(/\{(\w+)\}/g, function (match, name) {
      return Object.prototype.hasOwnProperty.call(vars, name) ? String(vars[name]) : match;
    });
  }

  function setKbdText(node, text) {
    var parts = text.split(/(\[[^\]]+\])/);
    node.replaceChildren.apply(node, parts.filter(Boolean).map(function (part) {
      var match = /^\[([^\]]+)\]$/.exec(part);
      if (!match) return document.createTextNode(part);
      var kbd = document.createElement('kbd');
      kbd.textContent = match[1];
      return kbd;
    }));
  }

  function applyStaticStrings() {
    document.documentElement.lang = uiReady(state.ui) ? state.ui : 'en';
    document.title = t('meta.title');
    var description = document.querySelector('meta[name="description"]');
    if (description) description.setAttribute('content', t('meta.description'));
    document.querySelectorAll('[data-i18n]').forEach(function (node) {
      node.textContent = t(node.getAttribute('data-i18n'));
    });
    document.querySelectorAll('[data-i18n-attr]').forEach(function (node) {
      node.getAttribute('data-i18n-attr').split(';').forEach(function (pair) {
        var bits = pair.split(':');
        if (bits.length === 2) node.setAttribute(bits[0].trim(), t(bits[1].trim()));
      });
    });
    renderUiButtons();
  }

  function renderUiButtons() {
    var buttons = I18N.languages.filter(function (l) { return uiReady(l.code); }).map(function (lang) {
      var button = document.createElement('button');
      button.type = 'button';
      button.className = 'lang-switch__btn';
      button.setAttribute('data-ui', lang.code);
      button.setAttribute('aria-pressed', String(lang.code === state.ui));
      var short = span('', lang.short);
      short.setAttribute('aria-hidden', 'true');
      button.append(short, span('visually-hidden', lang.name, lang.code));
      return button;
    });
    el.langButtons.replaceChildren.apply(el.langButtons, buttons);
  }

  function setUi(code) {
    if (!I18N[code]) return;
    state.ui = code;
    store.set('ui', code);
    applyStaticStrings();
    updateUrl();
    if (state.data) renderAll();
    var again = el.langButtons.querySelector('[data-ui="' + code + '"]');
    if (again) again.focus();
  }

  /* ------------------------------------------------------------------ */
  /* Helpers                                                             */
  /* ------------------------------------------------------------------ */

  function span(className, text, lang) {
    var node = document.createElement('span');
    if (className) node.className = className;
    if (text !== undefined && text !== null) node.textContent = text;
    if (lang) node.lang = lang;
    return node;
  }

  function make(tag, className, text) {
    var node = document.createElement(tag);
    if (className) node.className = className;
    if (text !== undefined && text !== null) node.textContent = text;
    return node;
  }

  function shuffled(list) {
    var copy = list.slice();
    for (var i = copy.length - 1; i > 0; i--) {
      var j = Math.floor(Math.random() * (i + 1));
      var tmp = copy[i];
      copy[i] = copy[j];
      copy[j] = tmp;
    }
    return copy;
  }

  function svgIcon(kind) {
    var ns = 'http://www.w3.org/2000/svg';
    var paths = {
      ok: 'm5 12.5 4.5 4.5L19 7.5',
      bad: 'm6.5 6.5 11 11M17.5 6.5l-11 11',
      sound: 'M4 9.5h3.5L12 5.5v13l-4.5-4H4zM15.5 8.5a5 5 0 0 1 0 7M18.5 5.5a9 9 0 0 1 0 13'
    };
    var svg = document.createElementNS(ns, 'svg');
    svg.setAttribute('viewBox', '0 0 24 24');
    svg.setAttribute('aria-hidden', 'true');
    svg.setAttribute('focusable', 'false');
    var path = document.createElementNS(ns, 'path');
    path.setAttribute('d', paths[kind]);
    svg.appendChild(path);
    return svg;
  }

  function reducedMotion() {
    return Boolean(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
  }

  /** Text with {X} -> text nodes and a visible "…" gap. */
  function fillText(node, text) {
    var parts = String(text).split('{X}');
    var children = [];
    parts.forEach(function (part, index) {
      if (index > 0) {
        var gap = span('gap', GAP);
        gap.title = t('card.gap');
        children.push(gap);
      }
      if (part) children.push(document.createTextNode(part));
    });
    node.replaceChildren.apply(node, children);
    return node;
  }

  function plain(text) {
    return String(text).split('{X}').join(GAP);
  }

  function entry(lang, id) {
    return state.byLang[lang] && state.byLang[lang][id];
  }

  /** One line for an entry: the text, or both forms "m / f". */
  function flat(e) {
    if (!e) return '';
    return e.forms ? plain(e.forms.m) + ' / ' + plain(e.forms.f) : plain(e.text);
  }

  function flatTranslit(e) {
    if (!e || !e.translit) return '';
    return typeof e.translit === 'object' ? plain(e.translit.m) + ' / ' + plain(e.translit.f) : plain(e.translit);
  }

  function langData(code) {
    return state.data.languages[code];
  }

  function langName(code) {
    var info = langData(code);
    var endonym = info ? info.endonym : code;
    try {
      var names = new Intl.DisplayNames([uiInfo(state.ui).locale], { type: 'language' });
      var name = names.of(code === 'no' ? 'nb' : code);
      if (name && name !== code && name !== 'nb') return name;
    } catch (error) { /* no Intl.DisplayNames */ }
    return endonym;
  }

  /** "ქართული (Georgisch)", or just the endonym when both are the same. */
  function langLabel(code) {
    var endonym = langData(code).endonym;
    var name = langName(code);
    return name.toLowerCase() === endonym.toLowerCase() ? endonym : endonym + ' (' + name + ')';
  }

  function sortedCodes() {
    var collator;
    try { collator = new Intl.Collator(uiInfo(state.ui).locale); } catch (error) { collator = null; }
    return state.codes.slice().sort(function (a, b) {
      var x = langName(a);
      var y = langName(b);
      return collator ? collator.compare(x, y) : (x < y ? -1 : 1);
    });
  }

  function groupName(groupId) {
    var group = state.data.groups.filter(function (g) { return g.id === groupId; })[0];
    if (!group) return groupId;
    return group[state.ui] || group.en;
  }

  /* ------------------------------------------------------------------ */
  /* Data                                                                */
  /* ------------------------------------------------------------------ */

  function loadScriptFallback() {
    return new Promise(function (resolve, reject) {
      if (window.LS_PHRASES) {
        resolve(window.LS_PHRASES);
        return;
      }
      var script = document.createElement('script');
      script.src = DATA_FALLBACK_URL;
      script.onload = function () {
        if (window.LS_PHRASES) resolve(window.LS_PHRASES);
        else reject(new Error('phrases.js did not define LS_PHRASES'));
      };
      script.onerror = function () { reject(new Error('phrases.js failed to load')); };
      document.head.appendChild(script);
    });
  }

  function loadPhrases() {
    if (window.location.protocol === 'file:' || !window.fetch) return loadScriptFallback();
    return fetch(DATA_URL)
      .then(function (response) {
        if (!response.ok) throw new Error('HTTP ' + response.status);
        return response.json();
      })
      .catch(loadScriptFallback);
  }

  function indexData(data) {
    if (!data || !data.languages || !Array.isArray(data.phrases) || !Array.isArray(data.groups)) {
      throw new Error('Invalid phrases data');
    }
    state.data = data;
    state.codes = Object.keys(data.languages);
    state.byLang = {};
    state.order = [];
    var seen = {};
    data.phrases.forEach(function (e) {
      (state.byLang[e.lang] = state.byLang[e.lang] || {})[e.id] = e;
      if (!seen[e.id]) {
        seen[e.id] = e.n;
        state.groupOf[e.id] = e.group;
        state.order.push(e.id);
      }
    });
    state.order.sort(function (a, b) { return seen[a] - seen[b]; });
    state.codes.forEach(function (code) {
      var entries = state.byLang[code] || {};
      state.checkedLang[code] = Object.keys(entries).length > 0 && Object.keys(entries).every(function (id) {
        return entries[id].checked === true;
      });
    });
  }

  function idsIn(groupId) {
    return state.order.filter(function (id) { return groupId === 'all' || state.groupOf[id] === groupId; });
  }

  /* ------------------------------------------------------------------ */
  /* URL and pair                                                        */
  /* ------------------------------------------------------------------ */

  function params() {
    try {
      return new URLSearchParams(window.location.search);
    } catch (error) {
      return { get: function () { return null; } };
    }
  }

  function updateUrl() {
    if (!window.history || !window.history.replaceState) return;
    var query = [];
    if (state.from) query.push('from=' + state.from);
    if (state.to) query.push('to=' + state.to);
    query.push('ui=' + state.ui);
    try {
      window.history.replaceState(null, '', window.location.pathname + '?' + query.join('&') + window.location.hash);
    } catch (error) { /* file:// in some browsers */ }
  }

  function shareUrl() {
    return PAGE_URL + '?from=' + state.from + '&to=' + state.to + '&ui=' + state.ui;
  }

  function browserLang() {
    var list = (navigator.languages && navigator.languages.length ? navigator.languages : [navigator.language || 'en']);
    for (var i = 0; i < list.length; i++) {
      var base = String(list[i]).toLowerCase().split('-')[0];
      if (base === 'nb' || base === 'nn') base = 'no';
      if (state.codes.indexOf(base) !== -1) return base;
    }
    return 'en';
  }

  function pickPair() {
    var p = params();
    var saved = store.get('pair', null) || {};
    var from = p.get('from');
    var to = p.get('to');
    var valid = function (code) { return code && state.codes.indexOf(code) !== -1; };
    state.from = valid(from) ? from : valid(saved.from) ? saved.from : browserLang();
    if (valid(to)) state.to = to;
    else if (!valid(from) && valid(saved.to)) state.to = saved.to;
    else state.to = '';
    if (state.to === state.from) state.to = '';
  }

  function setPair(from, to) {
    if (from === to) to = '';
    var changed = from !== state.from || to !== state.to;
    state.from = from;
    state.to = to;
    store.set('pair', { from: from, to: to });
    updateUrl();
    if (changed) {
      state.round = null;
      state.lastResult = null;
      loadPairProgress();
    }
    renderAll();
  }

  /* ------------------------------------------------------------------ */
  /* Chooser                                                             */
  /* ------------------------------------------------------------------ */

  function fillSelect(select, value, withEmpty) {
    var options = [];
    if (withEmpty) {
      var empty = document.createElement('option');
      empty.value = '';
      empty.textContent = t('chooser.empty');
      options.push(empty);
    }
    sortedCodes().forEach(function (code) {
      var option = document.createElement('option');
      option.value = code;
      option.textContent = langLabel(code);
      options.push(option);
    });
    select.replaceChildren.apply(select, options);
    select.value = value || '';
  }

  function renderChooser() {
    el.fromSelect.disabled = false;
    el.toSelect.disabled = false;
    fillSelect(el.fromSelect, state.from, false);
    fillSelect(el.toSelect, state.to, true);
    el.swapBtn.disabled = !state.to;
    el.copyBtn.hidden = !state.to;

    el.pickWrap.hidden = Boolean(state.to);
    if (!state.to) {
      var items = sortedCodes().filter(function (code) { return code !== state.from; }).map(function (code) {
        var li = document.createElement('li');
        var button = make('button', 'pick');
        button.type = 'button';
        button.setAttribute('data-to', code);
        var endonym = span('pick__endonym', langData(code).endonym, code);
        var name = span('pick__name', langName(code));
        var badge = span('pick__badge' + (state.checkedLang[code] ? ' is-checked' : ''), t(state.checkedLang[code] ? 'chooser.checked' : 'chooser.draft'));
        button.append(endonym, name, badge);
        li.appendChild(button);
        return li;
      });
      el.pickGrid.replaceChildren.apply(el.pickGrid, items);
    }
  }

  function copyLink() {
    var url = shareUrl();
    var done = function () { el.copyMsg.textContent = t('chooser.copied'); };
    var failed = function () { el.copyMsg.textContent = t('chooser.copyFailed'); };
    if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(url).then(done, failed);
    else failed();
  }

  /* ------------------------------------------------------------------ */
  /* Draft banner                                                        */
  /* ------------------------------------------------------------------ */

  function renderDraft() {
    var unchecked = [state.to, state.from].filter(function (code) { return code && !state.checkedLang[code]; });
    el.draft.hidden = unchecked.length === 0;
    if (unchecked.length) {
      el.draftText.textContent = t('draft.text', { langs: unchecked.map(function (c) { return langData(c).endonym; }).join(', ') });
    }
  }

  /* ------------------------------------------------------------------ */
  /* Phrase cards                                                        */
  /* ------------------------------------------------------------------ */

  function groupIds() {
    return state.data.groups.map(function (g) { return g.id; });
  }

  function renderChips() {
    var chips = groupIds().map(function (groupId) {
      var button = make('button', 'chip chip--' + groupId, groupName(groupId));
      button.type = 'button';
      button.setAttribute('data-group', groupId);
      button.setAttribute('aria-pressed', String(groupId === state.group));
      button.setAttribute('aria-controls', 'cards');
      return button;
    });
    el.groupChips.replaceChildren.apply(el.groupChips, chips);
  }

  function listenButton(lang, id, form, text) {
    var info = langData(lang);
    if (!voice.canPlay(lang, info.tts, id, form)) return null;
    var button = make('button', 'listen');
    button.type = 'button';
    button.setAttribute('data-listen', lang + '|' + id + '|' + (form || ''));
    button.setAttribute('aria-label', t('card.listenTo', { text: plain(text) }));
    button.append(svgIcon('sound'), span('listen__text', t('card.listen')));
    return button;
  }

  function translitNode(lang, value) {
    var node = fillText(make('p', 'phrase__translit'), value);
    node.lang = lang + '-Latn';
    return node;
  }

  function formTag(form) {
    var tag = span('form-tag', t(form === 'm' ? 'card.m' : 'card.f'));
    tag.setAttribute('aria-hidden', 'true');
    return [tag, span('visually-hidden', t(form === 'm' ? 'card.mLong' : 'card.fLong') + ': ')];
  }

  function learnBlock(lang, e) {
    var block = make('div', 'phrase__learn');
    if (e.forms) {
      var list = make('ul', 'phrase__forms');
      ['m', 'f'].forEach(function (form) {
        var li = make('li', 'phrase__form');
        var line = make('p', 'phrase__text');
        line.append.apply(line, formTag(form));
        line.appendChild(fillText(span('', null, lang), e.forms[form]));
        li.appendChild(line);
        if (e.translit) li.appendChild(translitNode(lang, e.translit[form]));
        var button = listenButton(lang, e.id, form, e.forms[form]);
        if (button) li.appendChild(button);
        list.appendChild(li);
      });
      block.appendChild(list);
      return block;
    }
    var text = fillText(make('p', 'phrase__text'), e.text);
    text.lang = lang;
    block.appendChild(text);
    if (e.translit) block.appendChild(translitNode(lang, e.translit));
    var single = listenButton(lang, e.id, null, e.text);
    if (single) block.appendChild(single);
    return block;
  }

  function mineBlock(lang, e) {
    var node = make('p', 'phrase__mine');
    node.lang = lang;
    if (!e) return node;
    if (e.forms) {
      ['m', 'f'].forEach(function (form, index) {
        if (index) node.appendChild(span('phrase__sep', ' / '));
        node.append.apply(node, formTag(form));
        node.appendChild(fillText(span(''), e.forms[form]));
      });
    } else {
      fillText(node, e.text);
    }
    return node;
  }

  function reportLink(lang, id, text) {
    var link = make('a', 'phrase__report', t('card.report'));
    link.href = 'mailto:' + MAIL + '?subject=' + encodeURIComponent('Language Starter: ' + lang + ' ' + id);
    link.setAttribute('aria-label', t('card.reportLabel', { text: text }));
    return link;
  }

  function buildCard(id) {
    var learned = entry(state.to, id);
    var mine = entry(state.from, id);
    var group = state.groupOf[id];
    var card = make('article', 'phrase phrase--' + group);
    card.setAttribute('data-id', id);

    var head = make('div', 'phrase__head');
    var number = span('phrase__n', String(learned.n));
    number.title = 'Nr. ' + learned.n;
    head.appendChild(number);
    if (group === 'numbers') head.appendChild(span('phrase__digit', id.split('.')[1]));
    card.appendChild(head);

    card.appendChild(learnBlock(state.to, learned));
    card.appendChild(mineBlock(state.from, mine));
    if (id === 'help.emergency') card.appendChild(make('p', 'phrase__hint', t('card.emergency')));
    card.appendChild(reportLink(state.to, id, flat(learned)));
    return card;
  }

  function renderCards() {
    el.cards.replaceChildren.apply(el.cards, idsIn(state.group).map(buildCard));
  }

  function onListen(button) {
    var bits = button.getAttribute('data-listen').split('|');
    var e = entry(bits[0], bits[1]);
    if (!e) return;
    var form = bits[2] || null;
    voice.play({
      lang: bits[0],
      tts: langData(bits[0]).tts,
      id: bits[1],
      form: form,
      text: form ? e.forms[form] : e.text
    });
  }

  /* ------------------------------------------------------------------ */
  /* Quiz: progress per language pair                                    */
  /* ------------------------------------------------------------------ */

  function pairKey() {
    return state.from + '-' + state.to;
  }

  function loadPairProgress() {
    state.progress = { rounds: 0, best: null, items: {} };
    state.round = null;
    state.lastResult = null;
    if (!state.to) return;
    var progress = store.get('progress:' + pairKey(), null);
    if (progress && typeof progress === 'object' && progress.items && typeof progress.items === 'object') {
      state.progress = {
        rounds: Number(progress.rounds) || 0,
        best: typeof progress.best === 'number' ? progress.best : null,
        items: progress.items
      };
    }
    var round = store.get('round:' + pairKey(), null);
    if (validRound(round)) state.round = round;
  }

  function validRound(round) {
    return round && Array.isArray(round.queue) && round.queue.length > 0 &&
      typeof round.index === 'number' && round.index >= 0 && round.index <= round.queue.length &&
      (round.dir === 'learn' || round.dir === 'say') &&
      round.queue.every(function (id) { return Boolean(state.groupOf[id]); });
  }

  function saveProgress() { store.set('progress:' + pairKey(), state.progress); }
  function saveRound() {
    if (state.round) store.set('round:' + pairKey(), state.round);
    else store.remove('round:' + pairKey());
  }
  function saveQuizSettings() { store.set('quiz', state.quiz); }

  function knownCount() {
    return state.order.filter(function (id) {
      var item = state.progress.items[id];
      return item && item.last === 'ok';
    }).length;
  }

  function formatPercent(value) {
    try {
      return new Intl.NumberFormat(uiInfo(state.ui).locale, { style: 'percent', maximumFractionDigits: 0 }).format(value / 100);
    } catch (error) {
      return value + ' %';
    }
  }

  /* ---------- start screen ---------- */

  function renderQuizStart() {
    var pills = [{ id: 'all', name: t('group.all') }].concat(groupIds().map(function (g) {
      return { id: g, name: groupName(g) };
    })).map(function (g) {
      var label = make('label', 'pill');
      var input = document.createElement('input');
      input.type = 'radio';
      input.name = 'group';
      input.value = g.id;
      input.checked = g.id === state.quiz.group;
      label.append(input, span('', g.name));
      return label;
    });
    el.quizGroups.replaceChildren.apply(el.quizGroups, pills);

    var learnName = langData(state.to).endonym;
    var mineName = langData(state.from).endonym;
    el.dirLearn.replaceChildren(span('', learnName, state.to), document.createTextNode(' → '), span('', mineName, state.from));
    el.dirSay.replaceChildren(span('', mineName, state.from), document.createTextNode(' → '), span('', learnName, state.to));
    el.startForm.querySelector('input[name="dir"][value="' + state.quiz.dir + '"]').checked = true;

    el.statKnown.textContent = t('stats.knownValue', { n: knownCount(), total: state.order.length });
    el.statBest.textContent = state.progress.best === null ? t('stats.none') : formatPercent(state.progress.best);
    el.statRounds.textContent = String(state.progress.rounds);

    var round = state.round;
    var resumable = round && round.index < round.queue.length;
    el.resumeBtn.hidden = !resumable;
    if (resumable) el.resumeBtn.textContent = t('start.resume', { n: round.index, done: answeredCount(round), total: round.queue.length });
    el.resetBtn.textContent = t(state.resetArmed ? 'stats.resetConfirm' : 'stats.reset');
  }

  function showScreen(name) {
    Object.keys(el.screens).forEach(function (key) { el.screens[key].hidden = key !== name; });
    state.screen = name;
  }

  /** Line the quiz card up under the sticky header, then move focus (like GeoAPP). */
  function focusSoon(node) {
    if (!node) return;
    window.setTimeout(function () {
      var card = document.querySelector('.quiz-card');
      var header = document.querySelector('.site-header');
      if (card) {
        var offset = (header ? header.offsetHeight : 0) + 12;
        var target = Math.max(0, card.getBoundingClientRect().top + window.scrollY - offset);
        if (Math.abs(window.scrollY - target) > 4) {
          window.scrollTo({ top: target, behavior: reducedMotion() ? 'instant' : 'smooth' });
        }
      }
      node.focus({ preventScroll: true });
    }, 0);
  }

  function openStart(focus) {
    state.resetArmed = false;
    el.resetMsg.textContent = '';
    renderQuizStart();
    showScreen('start');
    if (focus) focusSoon(el.startTitle);
  }

  function readStartForm() {
    var data = new FormData(el.startForm);
    var group = data.get('group');
    state.quiz.group = group === 'all' || groupIds().indexOf(group) !== -1 ? group : 'all';
    state.quiz.dir = data.get('dir') === 'say' ? 'say' : 'learn';
    saveQuizSettings();
  }

  function onReset() {
    if (!state.resetArmed) {
      state.resetArmed = true;
      el.resetBtn.textContent = t('stats.resetConfirm');
      el.resetMsg.textContent = '';
      return;
    }
    state.resetArmed = false;
    state.progress = { rounds: 0, best: null, items: {} };
    state.round = null;
    saveProgress();
    saveRound();
    renderQuizStart();
    el.resetMsg.textContent = t('stats.resetDone');
  }

  /* ---------- round ---------- */

  function startRound(ids, isRetry) {
    state.round = {
      dir: state.quiz.dir,
      group: state.quiz.group,
      retry: Boolean(isRetry),
      queue: shuffled(ids),
      index: 0,
      answered: false,
      correct: 0,
      wrong: []
    };
    saveRound();
    showScreen('question');
    showQuestion(true);
  }

  function answeredCount(round) {
    return round.index + (round.answered ? 1 : 0);
  }

  function resumeRound() {
    var round = state.round;
    if (!round) return;
    if (round.answered) {
      round.answered = false;
      round.index += 1;
    }
    saveRound();
    if (round.index >= round.queue.length) {
      finishRound();
      return;
    }
    showScreen('question');
    showQuestion(true);
  }

  function currentId() {
    var round = state.round;
    return round ? round.queue[round.index] : null;
  }

  /** The language shown in the prompt and the one used for the answers. */
  function quizLangs(dir) {
    return dir === 'learn' ? { prompt: state.to, answer: state.from } : { prompt: state.from, answer: state.to };
  }

  /** Correct answer plus three others from the same topic, all with a different text. */
  function buildOptions(id, answerLang) {
    var correctText = flat(entry(answerLang, id));
    var used = [correctText];
    var picks = [];
    var sameGroup = shuffled(idsIn(state.groupOf[id]).filter(function (other) { return other !== id; }));
    var others = shuffled(state.order.filter(function (other) { return state.groupOf[other] !== state.groupOf[id]; }));
    sameGroup.concat(others).forEach(function (other) {
      if (picks.length >= OPTION_COUNT - 1) return;
      var text = flat(entry(answerLang, other));
      if (used.indexOf(text) !== -1) return;
      used.push(text);
      picks.push(other);
    });
    return shuffled(picks.concat(id));
  }

  function showQuestion(moveFocus) {
    var round = state.round;
    var id = currentId();
    if (!id) {
      openStart(true);
      return;
    }
    var langs = quizLangs(round.dir);
    var e = entry(langs.prompt, id);
    state.options = buildOptions(id, langs.answer);

    el.word.lang = langs.prompt;
    el.word.replaceChildren();
    if (e.forms) {
      el.word.append(fillText(span(''), e.forms.m), span('prompt__sep', ' / '), fillText(span(''), e.forms.f));
    } else {
      fillText(el.word, e.text);
    }
    el.translit.lang = langs.prompt + '-Latn';
    el.translit.textContent = flatTranslit(e);
    el.translit.hidden = !e.translit;

    el.feedback.replaceChildren();
    el.feedback.className = 'feedback';
    el.nextBtn.hidden = true;
    renderQuestionTexts();
    renderOptions();
    saveRound();
    if (moveFocus) focusSoon(el.counter);
  }

  function renderQuestionTexts() {
    var round = state.round;
    if (!round) return;
    var total = round.queue.length;
    el.counter.textContent = t('q.counter', { n: round.index + 1, total: total });
    el.progressBar.max = total;
    el.progressBar.value = answeredCount(round);
    el.scoreOk.textContent = String(round.correct);
    el.scoreBad.textContent = String(round.wrong.length);
    el.promptLabel.textContent = t(round.dir === 'learn' ? 'q.promptMeaning' : 'q.promptSay');
    setKbdText(el.kbdHint, t('q.kbdChoice'));
    el.nextBtn.textContent = t(round.index + 1 >= total ? 'q.finish' : 'q.next');
  }

  function renderOptions() {
    var round = state.round;
    var answerLang = quizLangs(round.dir).answer;
    var buttons = state.options.map(function (id, index) {
      var button = make('button', 'option');
      button.type = 'button';
      button.setAttribute('data-id', id);
      var key = span('option__key', String(index + 1));
      key.setAttribute('aria-hidden', 'true');
      var word = span('option__word', flat(entry(answerLang, id)), answerLang);
      button.append(key, word, span('option__mark'));
      button.addEventListener('click', function () { answer(id); });
      return button;
    });
    el.options.replaceChildren.apply(el.options, buttons);
  }

  function recordAnswer(id, ok) {
    var item = state.progress.items[id] || { ok: 0, bad: 0, last: null };
    if (ok) item.ok += 1;
    else item.bad += 1;
    item.last = ok ? 'ok' : 'bad';
    state.progress.items[id] = item;
    saveProgress();
  }

  function answer(chosen) {
    var round = state.round;
    if (!round || round.answered) return;
    var id = currentId();
    var isCorrect = chosen === id;
    round.answered = true;
    round.lastChosen = chosen;
    if (isCorrect) round.correct += 1;
    else round.wrong.push(id);
    recordAnswer(id, isCorrect);
    saveRound();
    state.answeredAt = Date.now();
    markOptions(chosen, id);
    renderFeedback(isCorrect, id);
    renderQuestionTexts();
    el.nextBtn.hidden = false;
    el.nextBtn.focus();
  }

  function markOptions(chosen, correct) {
    el.options.querySelectorAll('.option').forEach(function (button) {
      var id = button.getAttribute('data-id');
      var mark = button.querySelector('.option__mark');
      button.disabled = true;
      mark.replaceChildren();
      if (id === correct) {
        button.classList.add('is-correct');
        mark.append(svgIcon('ok'), span('visually-hidden', ', ' + t('option.correct')));
      } else if (id === chosen) {
        button.classList.add('is-wrong');
        mark.append(svgIcon('bad'), span('visually-hidden', ', ' + t('option.yours')));
      } else {
        button.classList.add('is-muted');
      }
    });
  }

  function renderFeedback(isCorrect, id) {
    el.feedback.className = 'feedback ' + (isCorrect ? 'feedback--ok' : 'feedback--bad');
    var icon = span('feedback__icon');
    icon.appendChild(svgIcon(isCorrect ? 'ok' : 'bad'));
    var body = span('feedback__body');
    body.append(span('feedback__title', t(isCorrect ? 'fb.correct' : 'fb.wrong')));
    var learned = entry(state.to, id);
    var detail = span('feedback__detail');
    if (!isCorrect) detail.append(span('', t('fb.answerIs') + ' '));
    detail.append(span('feedback__learn', flat(learned), state.to));
    if (learned.translit) detail.append(document.createTextNode(' '), span('feedback__translit', '(' + flatTranslit(learned) + ')', state.to + '-Latn'));
    detail.append(document.createTextNode(' = '), span('', flat(entry(state.from, id)), state.from));
    body.append(detail);
    el.feedback.replaceChildren(icon, body);
  }

  function goNext(fromKeyboard) {
    var round = state.round;
    if (!round || !round.answered) return;
    if (fromKeyboard && Date.now() - state.answeredAt < NEXT_GUARD_MS) return;
    round.answered = false;
    round.index += 1;
    saveRound();
    if (round.index >= round.queue.length) finishRound();
    else showQuestion(true);
  }

  function finishRound() {
    var round = state.round;
    var total = round.queue.length;
    var percent = Math.round((round.correct / total) * 100);
    state.progress.rounds += 1;
    if (!round.retry) state.progress.best = state.progress.best === null ? percent : Math.max(state.progress.best, percent);
    saveProgress();
    state.lastResult = { dir: round.dir, group: round.group, total: total, correct: round.correct, percent: percent, wrong: round.wrong.slice() };
    state.round = null;
    saveRound();
    renderResult();
    showScreen('result');
    focusSoon(el.resultTitle);
  }

  function renderResult() {
    var result = state.lastResult;
    if (!result) return;
    el.rCorrect.textContent = String(result.correct);
    el.rTotal.textContent = String(result.total);
    el.rPercent.textContent = t('result.percent', { p: result.percent });
    el.percentShort.textContent = formatPercent(result.percent);
    el.ringValue.setAttribute('stroke-dasharray', result.percent + ' 100');
    el.rMessage.textContent = t(result.percent === 100 ? 'result.perfect' : result.percent >= 80 ? 'result.great' : result.percent >= 50 ? 'result.good' : 'result.low');

    var unique = result.wrong.filter(function (id, i, list) { return list.indexOf(id) === i; });
    el.rWrongWrap.hidden = unique.length === 0;
    el.retryBtn.hidden = unique.length === 0;
    el.retryBtn.textContent = t('result.retry', { n: unique.length });
    el.rWrong.replaceChildren.apply(el.rWrong, unique.map(function (id) {
      var learned = entry(state.to, id);
      var li = make('li', 'wrong__item');
      li.append(span('wrong__learn', flat(learned), state.to));
      if (learned.translit) li.append(span('wrong__translit', flatTranslit(learned), state.to + '-Latn'));
      li.append(span('wrong__answer', flat(entry(state.from, id)), state.from));
      return li;
    }));
  }

  function retryWrong() {
    var result = state.lastResult;
    if (!result || !result.wrong.length) return;
    state.quiz.dir = result.dir;
    startRound(result.wrong.filter(function (id, i, list) { return list.indexOf(id) === i; }), true);
  }

  function playAgain() {
    if (state.lastResult) {
      state.quiz.dir = state.lastResult.dir;
      state.quiz.group = state.lastResult.group;
    }
    startRound(idsIn(state.quiz.group), false);
  }

  function renderQuiz() {
    if (state.screen === 'question' && state.round) {
      renderQuestionTexts();
      renderOptions();
      if (state.round.answered) {
        markOptions(state.round.lastChosen, currentId());
        renderFeedback(state.round.lastChosen === currentId(), currentId());
      }
    } else if (state.screen === 'result' && state.lastResult) {
      renderResult();
    } else {
      openStart(false);
    }
  }

  function onKeydown(event) {
    if (event.ctrlKey || event.metaKey || event.altKey || event.defaultPrevented) return;
    if (state.screen !== 'question' || !state.round || !state.to) return;
    var target = event.target;
    var tag = target && target.tagName;
    if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT' || (target && target.isContentEditable)) return;

    if (!state.round.answered && /^[1-4]$/.test(event.key)) {
      var index = Number(event.key) - 1;
      if (index < state.options.length) {
        event.preventDefault();
        answer(state.options[index]);
      }
      return;
    }
    if (event.key === 'Enter' && state.round.answered) {
      if (tag !== 'BUTTON' && tag !== 'A' && tag !== 'SUMMARY') {
        event.preventDefault();
        goNext(true);
      }
    }
  }

  /* ------------------------------------------------------------------ */
  /* Sprachkarte (print)                                                 */
  /* ------------------------------------------------------------------ */

  function qrSvg(text) {
    var ns = 'http://www.w3.org/2000/svg';
    var svg = document.createElementNS(ns, 'svg');
    svg.setAttribute('class', 'sheet__qr-code');
    svg.setAttribute('role', 'img');
    svg.setAttribute('aria-label', 'QR code: ' + text);
    if (typeof window.qrcode !== 'function') return svg;
    var qr = window.qrcode(0, 'M');
    qr.addData(text);
    qr.make();
    var count = qr.getModuleCount();
    var quiet = 2;
    var d = '';
    for (var row = 0; row < count; row++) {
      for (var col = 0; col < count; col++) {
        if (qr.isDark(row, col)) d += 'M' + (col + quiet) + ' ' + (row + quiet) + 'h1v1h-1z';
      }
    }
    var size = count + quiet * 2;
    svg.setAttribute('viewBox', '0 0 ' + size + ' ' + size);
    svg.setAttribute('shape-rendering', 'crispEdges');
    var bg = document.createElementNS(ns, 'rect');
    bg.setAttribute('width', String(size));
    bg.setAttribute('height', String(size));
    bg.setAttribute('fill', '#fff');
    var path = document.createElementNS(ns, 'path');
    path.setAttribute('d', d);
    path.setAttribute('fill', '#000');
    svg.append(bg, path);
    return svg;
  }

  function sheetText(lang, e, field) {
    var value = e[field];
    var node = span('sheet__' + (field === 'translit' ? 'translit' : 'text'));
    node.lang = field === 'translit' ? lang + '-Latn' : lang;
    if (e.forms) {
      var forms = field === 'translit' ? value : e.forms;
      ['m', 'f'].forEach(function (form, index) {
        if (index) node.appendChild(document.createTextNode(' / '));
        node.appendChild(fillText(span(''), forms[form]));
        var tag = span('sheet__form', t(form === 'm' ? 'card.m' : 'card.f'));
        node.appendChild(tag);
      });
    } else {
      fillText(node, value);
    }
    return node;
  }

  function renderSheet() {
    var sheet = el.sheet;
    var inner = make('div', 'sheet__inner');

    var head = make('header', 'sheet__head');
    var titles = make('div', 'sheet__titles');
    var title = make('h3', 'sheet__title');
    title.append(
      document.createTextNode('Language Starter · '),
      span('', langData(state.from).endonym, state.from),
      document.createTextNode(' → '),
      span('', langData(state.to).endonym, state.to)
    );
    titles.appendChild(title);
    if (!state.checkedLang[state.to] || !state.checkedLang[state.from]) titles.appendChild(make('p', 'sheet__draft', t('sheet.draft')));
    var qr = make('figure', 'sheet__qr');
    qr.append(qrSvg(shareUrl()), make('figcaption', '', t('sheet.scan')));
    head.append(titles, qr);

    var cols = make('div', 'sheet__cols');
    groupIds().forEach(function (groupId) {
      var section = make('section', 'sheet__group sheet__group--' + groupId);
      section.appendChild(make('h4', 'sheet__group-title', groupName(groupId)));
      var list = make('dl', 'sheet__list');
      idsIn(groupId).forEach(function (id) {
        var learned = entry(state.to, id);
        var row = make('div', 'sheet__row');
        var dt = document.createElement('dt');
        if (groupId === 'numbers') dt.appendChild(span('sheet__digit', id.split('.')[1]));
        dt.appendChild(sheetText(state.to, learned, 'text'));
        if (learned.translit) dt.appendChild(sheetText(state.to, learned, 'translit'));
        var dd = document.createElement('dd');
        dd.appendChild(sheetText(state.from, entry(state.from, id), 'text'));
        row.append(dt, dd);
        list.appendChild(row);
      });
      section.appendChild(list);
      cols.appendChild(section);
    });

    var foot = make('footer', 'sheet__foot');
    foot.append(span('sheet__url', PAGE_URL.replace('https://', '')), span('', t('sheet.footer')));

    inner.append(head, cols, foot);
    sheet.replaceChildren(inner);
    sheet.setAttribute('lang', state.ui);
    fitSheet();
  }

  /**
   * The sheet has the A4 ratio and all its sizes are in container units, so
   * what fits on screen fits on paper. Shrink the type until it fits.
   */
  function fitSheet() {
    var sheet = el.sheet;
    var inner = sheet.firstElementChild;
    if (!inner || !sheet.offsetWidth) return;
    var scale = 1;
    sheet.style.setProperty('--fit', '1');
    var limit = function () {
      var style = window.getComputedStyle(sheet);
      return sheet.clientHeight - parseFloat(style.paddingTop) - parseFloat(style.paddingBottom);
    };
    var guard = 0;
    while (inner.scrollHeight > limit() * 0.985 && scale > 0.55 && guard < 40) {
      scale -= 0.025;
      guard += 1;
      sheet.style.setProperty('--fit', scale.toFixed(3));
    }
    sheet.setAttribute('data-fit', scale.toFixed(3));
  }

  /* ------------------------------------------------------------------ */
  /* Review mode (?review=fi)                                            */
  /* ------------------------------------------------------------------ */

  function renderReview(code) {
    document.documentElement.classList.add('is-review');
    var robots = document.createElement('meta');
    robots.name = 'robots';
    robots.content = 'noindex, nofollow';
    document.head.appendChild(robots);
    document.documentElement.lang = 'en';

    var wrap = el.review;
    wrap.hidden = false;
    var info = state.data.languages[code];
    var title = make('h1', 'review__title');
    var lines = make('div', 'review__intro');
    var en = make('p', '', 'Please reply to Iva\'s e-mail with the number and your version, for example "12: …". The phrases use the informal "you".');
    en.lang = 'en';
    var de = make('p', '', 'Bitte antworte auf Ivas E-Mail mit der Nummer und deiner Version, zum Beispiel „12: …“. Die Sätze verwenden das informelle „du“.');
    de.lang = 'de';
    lines.append(en, de);

    if (!info) {
      document.title = 'Language Starter: review';
      title.textContent = 'Language Starter: review';
      var known = make('p', 'review__error', 'Unknown language code "' + code + '". Use one of: ' + state.codes.join(', ') + '.');
      wrap.replaceChildren(title, known);
      return;
    }

    document.title = 'Language Starter: review ' + info.endonym + ' (' + code + ')';
    title.append(document.createTextNode('Language Starter: review · '), span('', info.endonym, code), document.createTextNode(' (' + code + ')'));

    var actions = make('p', 'review__actions');
    var print = make('button', 'btn btn--primary review__print', 'Drucken / Print');
    print.type = 'button';
    print.addEventListener('click', function () { window.print(); });
    actions.appendChild(print);

    var hasTranslit = state.order.some(function (id) { return Boolean(entry(code, id).translit); });
    var table = make('table', 'review__table');
    var thead = document.createElement('thead');
    var headRow = document.createElement('tr');
    ['Nr.', 'English', 'Meaning', 'Translation: ' + info.endonym].concat(hasTranslit ? ['Latin spelling'] : []).forEach(function (label) {
      var th = make('th', '', label);
      th.scope = 'col';
      headRow.appendChild(th);
    });
    thead.appendChild(headRow);
    var tbody = document.createElement('tbody');
    state.order.forEach(function (id) {
      var e = entry(code, id);
      var base = entry('en', id) || {};
      var tr = document.createElement('tr');
      var n = make('th', 'review__n', String(e.n));
      n.scope = 'row';
      var english = make('td', '', plain(base.text || ''));
      english.lang = 'en';
      var meaning = make('td', 'review__meaning', plain(base.meaning || ''));
      meaning.lang = 'en';
      var translation = document.createElement('td');
      translation.lang = code;
      translation.textContent = e.forms ? 'm: ' + plain(e.forms.m) + ' / f: ' + plain(e.forms.f) : plain(e.text);
      tr.append(n, english, meaning, translation);
      if (hasTranslit) {
        var latin = make('td', '', e.translit ? (typeof e.translit === 'object' ? 'm: ' + plain(e.translit.m) + ' / f: ' + plain(e.translit.f) : plain(e.translit)) : '');
        latin.lang = code + '-Latn';
        tr.appendChild(latin);
      }
      tbody.appendChild(tr);
    });
    table.append(thead, tbody);
    // On a narrow phone the table may still be wider than the screen: let it scroll on its own.
    var scroller = make('div', 'review__scroll');
    scroller.setAttribute('role', 'region');
    scroller.setAttribute('aria-label', 'Phrases');
    scroller.tabIndex = 0;
    scroller.appendChild(table);
    wrap.replaceChildren(title, lines, actions, scroller);
  }

  /* ------------------------------------------------------------------ */
  /* Render everything that depends on the pair                          */
  /* ------------------------------------------------------------------ */

  function renderThanks() {
    var names = [];
    state.codes.forEach(function (code) {
      (langData(code).reviewers || []).forEach(function (name) { names.push(name + ' (' + langData(code).endonym + ')'); });
    });
    el.thanks.hidden = names.length === 0;
    el.thanksList.replaceChildren.apply(el.thanksList, names.map(function (name) { return make('li', '', name); }));
  }

  function renderAll() {
    renderChooser();
    renderThanks();
    el.pair.hidden = !state.to;
    if (!state.to) return;
    renderDraft();
    renderChips();
    renderCards();
    renderQuiz();
    renderSheet();
  }

  /* ------------------------------------------------------------------ */
  /* Wiring                                                              */
  /* ------------------------------------------------------------------ */

  function wire() {
    el.langButtons.addEventListener('click', function (event) {
      var button = event.target.closest('[data-ui]');
      if (button) setUi(button.getAttribute('data-ui'));
    });
    el.fromSelect.addEventListener('change', function () { setPair(el.fromSelect.value, state.to === el.fromSelect.value ? '' : state.to); });
    el.toSelect.addEventListener('change', function () { setPair(state.from, el.toSelect.value); });
    el.swapBtn.addEventListener('click', function () {
      if (state.to) setPair(state.to, state.from);
      el.swapBtn.focus();
    });
    el.copyBtn.addEventListener('click', copyLink);
    el.pickGrid.addEventListener('click', function (event) {
      var button = event.target.closest('[data-to]');
      if (!button) return;
      setPair(state.from, button.getAttribute('data-to'));
      el.toSelect.focus();
    });
    el.groupChips.addEventListener('click', function (event) {
      var button = event.target.closest('[data-group]');
      if (!button) return;
      state.group = button.getAttribute('data-group');
      store.set('group', state.group);
      renderChips();
      renderCards();
      var again = el.groupChips.querySelector('[data-group="' + state.group + '"]');
      if (again) again.focus();
    });
    el.cards.addEventListener('click', function (event) {
      var button = event.target.closest('[data-listen]');
      if (button) onListen(button);
    });

    el.startForm.addEventListener('change', readStartForm);
    el.startForm.addEventListener('submit', function (event) {
      event.preventDefault();
      readStartForm();
      startRound(idsIn(state.quiz.group), false);
    });
    el.resumeBtn.addEventListener('click', resumeRound);
    el.resetBtn.addEventListener('click', onReset);
    el.nextBtn.addEventListener('click', function (event) { goNext(event.detail === 0); });
    el.quitBtn.addEventListener('click', function () { openStart(true); });
    el.retryBtn.addEventListener('click', retryWrong);
    el.againBtn.addEventListener('click', playAgain);
    el.settingsBtn.addEventListener('click', function () { openStart(true); });
    document.addEventListener('keydown', onKeydown);

    el.printBtn.addEventListener('click', function () {
      fitSheet();
      window.print();
    });
    window.addEventListener('beforeprint', fitSheet);

    var resizeTimer = 0;
    window.addEventListener('resize', function () {
      window.clearTimeout(resizeTimer);
      resizeTimer = window.setTimeout(fitSheet, 150);
    });
    // A network voice may stop working offline: redraw the Listen buttons.
    ['online', 'offline'].forEach(function (name) {
      window.addEventListener(name, function () { if (state.to) renderCards(); });
    });
  }

  /* ------------------------------------------------------------------ */
  /* Boot                                                                */
  /* ------------------------------------------------------------------ */

  function pickUi() {
    var fromUrl = params().get('ui');
    if (fromUrl && I18N[fromUrl]) return fromUrl;
    var saved = store.get('ui', null);
    if (saved && uiReady(saved)) return saved;
    var nav = String(navigator.language || 'en').toLowerCase().split('-')[0];
    return uiReady(nav) ? nav : I18N.defaultLang;
  }

  function registerServiceWorker() {
    if (!('serviceWorker' in navigator)) return;
    var secure = window.location.protocol === 'https:' || window.location.hostname === 'localhost';
    if (!secure) return;
    window.addEventListener('load', function () {
      navigator.serviceWorker.register('sw.js').catch(function () { /* offline mode is a bonus */ });
    });
  }

  function boot() {
    var review = params().get('review');
    if (review) {
      document.documentElement.classList.add('is-review');
      document.documentElement.classList.remove('i18n-pending');
      loadPhrases().then(function (data) {
        indexData(data);
        renderReview(String(review).toLowerCase());
      }).catch(function () {
        el.review.hidden = false;
        el.review.textContent = 'The phrases could not be loaded. Please reload the page.';
      });
      return;
    }

    state.ui = pickUi();
    applyStaticStrings();
    document.documentElement.classList.remove('i18n-pending');
    el.storageNotice.hidden = store.available;
    var savedQuiz = store.get('quiz', null);
    if (savedQuiz && typeof savedQuiz === 'object') {
      if (savedQuiz.dir === 'say' || savedQuiz.dir === 'learn') state.quiz.dir = savedQuiz.dir;
      if (typeof savedQuiz.group === 'string') state.quiz.group = savedQuiz.group;
    }
    var savedGroup = store.get('group', null);
    if (typeof savedGroup === 'string') state.group = savedGroup;
    wire();
    registerServiceWorker();

    Promise.all([loadPhrases(), voice.init()])
      .then(function (results) {
        indexData(results[0]);
        if (groupIds().indexOf(state.group) === -1) state.group = groupIds()[0];
        if (state.quiz.group !== 'all' && groupIds().indexOf(state.quiz.group) === -1) state.quiz.group = 'all';
        pickPair();
        store.set('pair', { from: state.from, to: state.to });
        updateUrl();
        loadPairProgress();
        el.status.hidden = true;
        renderAll();
      })
      .catch(function () {
        el.status.classList.add('is-error');
        el.status.setAttribute('data-i18n', 'error');
        el.status.textContent = t('error');
      });
  }

  boot();
})();
